#!/usr/bin/env python3
# GENERATED by PrototypeFramework 0.9.0 from Documentation~/agent/tools/font-check.py — do not edit here. Change it in the framework repo, then run Framework/Agent Docs/Sync (editor) or Tools/Build/pf-build.sh agentdocs.
"""font-check.py — no TMP font asset may be built from a VARIABLE font.

    Tools/pf/font-check.py --check [ROOT]                       # gate: every TMP font asset under Assets/
    Tools/pf/font-check.py --instance FONT.ttf --weights 800,900 [--out DIR]
                                                                # write static <Family>-<Weight>.ttf

WHY. TextMesh Pro rasterises a font file through FreeType without choosing a variation instance, so
an asset built from a variable font (one with an `fvar` table, e.g. `Nunito[wght].ttf`) draws the
font's DEFAULT instance — whatever weight the type designer put at the axis default — and nothing a
DesignTokens weight, a material or a `<b>` tag says changes that. Measured on a SKU (SortingPuzzle,
epics 1-12): all 170 TMP texts used `Nunito SDF`, built from Nunito[wght] (axis 200-1000, default
200 = ExtraLight). DESIGN.md asked for 900 / 800 / 600-800; every text in the game shipped
ExtraLight, every `visual-judge` run passed, and no gate looked at type weight. Its two fallbacks
(`Nunito Sans SDF`, `Noto Sans Thai SDF`) were variable too. The defect is invisible in code review
and in the asset inspector; it is visible in the font file's table directory, so it is checked
there.

--check (stdlib only, no Unity, no fontTools)
  * finds every TMP font asset under ROOT/Assets/ (a YAML `.asset` naming `m_SourceFontFile` /
    `m_SourceFontFileGUID`), resolves its source font through the `.meta` guid map (Assets/ and
    local Packages/), and reads the font's sfnt table directory for an `fvar` tag;
  * follows `m_FallbackFontAssetTable`, so a variable font reached only as a fallback (including a
    fallback asset that lives outside Assets/) is caught and named with the asset that reaches it;
  * reports, per offending asset, the source file, the axis range and the DEFAULT instance weight
    (the `wght` axis default from `fvar`, else OS/2 usWeightClass) — the weight TMP actually draws —
    and the command that writes static instances.
  A `.ttc` / `.woff` / `.woff2` source, a binary-serialised asset or a guid that resolves to nothing
  is said ("cannot read …") and does not fail the check; a missing Assets/ is no TMP font at all.

--instance (needs fontTools)
  writes one STATIC font per weight, every other axis pinned to its default, named
  `<Family>-<Weight>.ttf` beside the source (or in --out). Never writes over the variable source. No
  fontTools in this python: re-runs itself through `uv run --quiet --with fonttools python` when `uv`
  is on PATH, else exits 2 naming the install command. Then rebuild each TMP font asset from its
  static instance (Font Asset Creator, through Unity-MCP — never by hand-editing the .asset YAML),
  and point the type-role tokens at those assets.

Exit-code contract: 0 Ok · 1 Drift · 2 Error.
  --check     0 no TMP font asset reaches a variable source (or there is no TMP font asset at all)
              1 at least one does
              2 ROOT is not a Unity project (neither ProjectSettings/ nor Assets/ — a greps.sh
                fixture tree with only Assets/ is checked, and passes when it holds no font asset)
  --instance  0 every requested weight written · 2 anything else (no fontTools, a weight outside
              the axis, not a variable font, would overwrite the source)
"""
import argparse, os, re, shutil, struct, subprocess, sys

TAG = "[font-check]"
SOURCE_RX = re.compile(rb"m_SourceFontFile(?:GUID)?\s*:")
SRC_GUID_RX = re.compile(rb"m_SourceFontFileGUID:\s*([0-9a-f]{32})")
SRC_REF_RX = re.compile(rb"m_SourceFontFile:\s*\{[^}]*guid:\s*([0-9a-f]{32})")
FALLBACK_RX = re.compile(rb"m_FallbackFontAssetTable:\s*\n((?:\s*-\s*\{[^}]*\}\s*\n)*)")
GUID_RX = re.compile(rb"guid:\s*([0-9a-f]{32})")
NAME_RX = re.compile(rb"^--- !u!114 &11400000\b.*?^\s*m_Name:\s*(.*?)\s*$", re.M | re.S)
WEIGHT_NAMES = {100: "Thin", 200: "ExtraLight", 300: "Light", 400: "Regular", 500: "Medium",
                600: "SemiBold", 700: "Bold", 800: "ExtraBold", 900: "Black", 1000: "ExtraBlack"}
SKIP_DIRS = {"Library", "Temp", "Logs", "obj", "Build", "Builds", ".git", "UserSettings"}


# --- sfnt ---------------------------------------------------------------------------------------

def sfnt_info(path):
    """{'variable', 'axes': [(tag, min, default, max)], 'weight'} or {'error': why}. Stdlib only."""
    try:
        with open(path, "rb") as fh:
            data = fh.read()
    except OSError as e:
        return {"error": f"cannot read ({e.strerror})"}
    if len(data) < 12:
        return {"error": "cannot read (not a font file)"}
    tag = data[:4]
    if tag == b"ttcf":
        return {"error": "cannot read a .ttc collection — check its members one by one"}
    if tag in (b"wOFF", b"wOF2"):
        return {"error": "cannot read a WOFF font — TMP needs the .ttf/.otf anyway"}
    if tag not in (b"\x00\x01\x00\x00", b"OTTO", b"true", b"typ1"):
        return {"error": "cannot read (unknown sfnt version)"}
    (num,) = struct.unpack(">H", data[4:6])
    tables = {}
    for i in range(num):
        rec = data[12 + 16 * i: 28 + 16 * i]
        if len(rec) < 16:
            return {"error": "cannot read (truncated table directory)"}
        t, _, off, ln = struct.unpack(">4sIII", rec)
        tables[t] = (off, ln)
    info = {"variable": b"fvar" in tables, "axes": [], "weight": None}
    if b"OS/2" in tables:
        off, ln = tables[b"OS/2"]
        if ln >= 6:
            info["weight"] = struct.unpack(">H", data[off + 4: off + 6])[0]
    if info["variable"]:
        off, _ = tables[b"fvar"]
        try:
            _, _, axes_off, _, count, size = struct.unpack(">HHHHHH", data[off: off + 12])
            for i in range(count):
                a = off + axes_off + i * size
                t, mn, df, mx = struct.unpack(">4siii", data[a: a + 16])
                info["axes"].append((t.decode("latin-1"), mn / 65536, df / 65536, mx / 65536))
        except struct.error:
            pass
        for t, mn, df, mx in info["axes"]:
            if t == "wght":
                info["weight"] = df
    return info


def weight_label(w):
    if w is None:
        return "unknown weight"
    w = int(round(w))
    return f"{w} {WEIGHT_NAMES.get(w, '')}".strip()


# --- the Unity side -----------------------------------------------------------------------------

def walk(top, exts):
    for d, dirs, files in os.walk(top):
        dirs[:] = [x for x in dirs if x not in SKIP_DIRS and not x.startswith(".")]
        for f in files:
            if f.endswith(exts):
                yield os.path.join(d, f)


def guid_map(root):
    """guid → asset path, from every .meta under Assets/ and the local (non-cache) Packages/."""
    out = {}
    for top in ("Assets", "Packages"):
        for meta in walk(os.path.join(root, top), (".meta",)):
            try:
                with open(meta, "rb") as fh:
                    m = re.search(rb"^guid:\s*([0-9a-f]{32})", fh.read(512), re.M)
            except OSError:
                continue
            if m:
                out[m.group(1).decode()] = meta[:-5]
    return out


def read_font_asset(path):
    """{'name', 'source_guid', 'fallbacks': [guid]} for a TMP font asset, None if not one, or {'error'}."""
    try:
        with open(path, "rb") as fh:
            data = fh.read()
    except OSError as e:
        return {"error": f"cannot read ({e.strerror})"}
    if not SOURCE_RX.search(data):
        if not data.startswith(b"%YAML") and b"m_SourceFontFile" in data:
            return {"error": "binary-serialised asset — cannot read; set Asset Serialization to Force Text"}
        return None
    m = SRC_GUID_RX.search(data) or SRC_REF_RX.search(data)
    name = NAME_RX.search(data)
    fb = FALLBACK_RX.search(data)
    return {"name": name.group(1).decode("utf-8", "replace") if name else os.path.basename(path)[:-6],
            "source_guid": m.group(1).decode() if m else None,
            "fallbacks": [g.decode() for g in GUID_RX.findall(fb.group(1))] if fb else []}


def check(root):
    root = os.path.abspath(root)
    assets_dir = os.path.join(root, "Assets")
    if not os.path.isdir(os.path.join(root, "ProjectSettings")) and not os.path.isdir(assets_dir):
        print(f"{TAG} ERROR: {root} is not a Unity project (no ProjectSettings/, no Assets/)", file=sys.stderr)
        return 2
    if not os.path.isdir(assets_dir):
        print(f"{TAG} PASS  no Assets/ — no TMP font asset to check")
        return 0
    rel = lambda p: os.path.relpath(p, root)
    guids = guid_map(root)
    assets, notes = {}, []                              # path → parsed font asset
    for p in walk(assets_dir, (".asset",)):
        a = read_font_asset(p)
        if a is None:
            continue
        if "error" in a:
            notes.append(f"{rel(p)}: {a['error']}")
            continue
        assets[p] = a
    # Fallbacks outside Assets/ (a package's font asset) are read too: a variable font reached only as
    # a fallback still draws its default instance for every glyph the primary lacks.
    reached_by = {}
    queue = list(assets)
    while queue:
        p = queue.pop()
        for g in assets[p]["fallbacks"]:
            fp = guids.get(g)
            if not fp:
                continue
            reached_by.setdefault(fp, []).append(assets[p]["name"])
            if fp not in assets:
                a = read_font_asset(fp)
                if a and "error" not in a:
                    assets[fp] = a
                    queue.append(fp)
    if not assets:
        print(f"{TAG} PASS  no TMP font asset under Assets/ (nothing to check)")
        for n in notes:
            print(f"{TAG}   note: {n}")
        return 0

    bad, ok, fonts = [], [], {}
    for p, a in sorted(assets.items(), key=lambda kv: kv[1]["name"].lower()):
        src = guids.get(a["source_guid"] or "")
        if not src:
            notes.append(f"{a['name']} ({rel(p)}): source font guid {a['source_guid'] or '(none)'} "
                         f"resolves to no file — cannot check it")
            continue
        info = fonts.setdefault(src, sfnt_info(src))
        if "error" in info:
            notes.append(f"{a['name']}: source {rel(src)} — {info['error']}")
            continue
        (bad if info["variable"] else ok).append((p, a, src, info))

    for p, a, src, info in bad:
        axes = ", ".join(f"{t} {mn:g}-{mx:g} default {df:g}" for t, mn, df, mx in info["axes"])
        via = reached_by.get(p)
        print(f"{TAG} VIOLATION {rel(p)} — '{a['name']}' is built from a VARIABLE font")
        print(f"{TAG}   source  {rel(src)}  (fvar: {axes or 'no axes read'})")
        print(f"{TAG}   draws   {weight_label(info['weight'])} — TMP renders only the default instance")
        if via:
            print(f"{TAG}   reached as a fallback of: {', '.join(sorted(set(via)))}")
        print(f"{TAG}   fix     python3 Tools/pf/font-check.py --instance '{rel(src)}' --weights <your type roles' weights, e.g. 400,800,900>")
        print(f"{TAG}           then rebuild the TMP font asset from each static <Family>-<Weight>.ttf (Font Asset Creator, via Unity-MCP)")
    for n in notes:
        print(f"{TAG}   note: {n}")
    if bad:
        print(f"{TAG} FAIL  {len(bad)} of {len(bad) + len(ok)} TMP font asset(s) built from a variable font")
        return 1
    print(f"{TAG} PASS  {len(ok)} TMP font asset(s), every source font static")
    return 0


# --- --instance ---------------------------------------------------------------------------------

def ensure_fonttools(argv):
    try:
        import fontTools  # noqa: F401
        return
    except ImportError:
        pass
    uv = shutil.which("uv")
    if uv and not os.environ.get("PF_FONT_CHECK_REEXEC"):
        env = dict(os.environ, PF_FONT_CHECK_REEXEC="1")
        cmd = [uv, "run", "--quiet", "--with", "fonttools", "python", os.path.abspath(__file__)] + argv
        sys.exit(subprocess.run(cmd, env=env).returncode)
    print(f"{TAG} ERROR: --instance needs fontTools, which this python cannot import, and no `uv` is on PATH.\n"
          f"          python3 -m pip install --user fonttools      (then re-run this command)\n"
          f"       or install uv (https://docs.astral.sh/uv/) — this tool then runs itself through\n"
          f"          uv run --quiet --with fonttools python, with nothing installed globally",
          file=sys.stderr)
    sys.exit(2)


def family_name(font):
    name = font["name"]
    for nid in (16, 1):
        rec = name.getDebugName(nid)
        if rec:
            return re.sub(r"[^A-Za-z0-9]", "", rec)
    return "Font"


def instance(src, weights, out_dir):
    from fontTools.ttLib import TTFont
    from fontTools.varLib import instancer
    src = os.path.abspath(src)
    if not os.path.isfile(src):
        print(f"{TAG} ERROR: no font at {src}", file=sys.stderr)
        return 2
    font = TTFont(src)
    if "fvar" not in font:
        print(f"{TAG} ERROR: {src} has no fvar table — it is already static; build the TMP asset from it as is",
              file=sys.stderr)
        return 2
    axes = {a.axisTag: (a.minValue, a.defaultValue, a.maxValue) for a in font["fvar"].axes}
    if "wght" not in axes:
        print(f"{TAG} ERROR: {src} has no wght axis (axes: {', '.join(axes)})", file=sys.stderr)
        return 2
    lo, _, hi = axes["wght"]
    outside = [w for w in weights if not lo <= w <= hi]
    if outside:
        print(f"{TAG} ERROR: weight(s) {', '.join(map(str, outside))} outside the wght axis {lo:g}-{hi:g}",
              file=sys.stderr)
        return 2
    family = family_name(font)
    out_dir = os.path.abspath(out_dir or os.path.dirname(src))
    os.makedirs(out_dir, exist_ok=True)
    plan = [(w, os.path.join(out_dir, f"{family}-{w}.ttf")) for w in weights]
    for _, path in plan:
        if os.path.exists(path) and os.path.samefile(path, src):
            print(f"{TAG} ERROR: {path} is the variable source — refusing to overwrite it; pass --out",
                  file=sys.stderr)
            return 2
    for w, path in plan:
        limits = {t: d for t, (_, d, _) in axes.items()}     # every other axis pinned to its default
        limits["wght"] = w
        f = TTFont(src)
        try:
            static = instancer.instantiateVariableFont(f, limits, updateFontNames=True)
        except Exception:
            f = TTFont(src)                                  # no STAT table to rename from: keep names
            static = instancer.instantiateVariableFont(f, limits)
        if "OS/2" in static:
            static["OS/2"].usWeightClass = int(w)
        if "fvar" in static:
            print(f"{TAG} ERROR: {path} still has an fvar table — not written", file=sys.stderr)
            return 2
        existed = os.path.exists(path)
        static.save(path)
        print(f"{TAG} wrote {path}  (wght {w} {WEIGHT_NAMES.get(w, '')}".rstrip() + (", replaced" if existed else "") + ")")
    print(f"{TAG} next: build one TMP font asset per file (Font Asset Creator, via Unity-MCP) and point the "
          f"type-role tokens at them; delete the variable-font asset once nothing references it")
    return 0


def main(argv):
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--check", nargs="?", const="", metavar="ROOT",
                    help="check every TMP font asset under ROOT/Assets (default: the repo this tool is synced into)")
    ap.add_argument("--instance", metavar="FONT", help="a variable .ttf/.otf to write static instances of")
    ap.add_argument("--weights", help="--instance: comma-separated wght values, e.g. 800,900")
    ap.add_argument("--out", help="--instance: output folder (default: beside the source)")
    a = ap.parse_args(argv)
    if (a.check is not None) == bool(a.instance):
        ap.print_usage(sys.stderr)
        print(f"{TAG} ERROR: give exactly one of --check [ROOT] or --instance FONT --weights …", file=sys.stderr)
        return 2
    if a.check is not None:
        # No ROOT: the working directory when it is a Unity project, else the repo this tool lives in
        # (Tools/pf/ → ../..), so `Tools/pf/font-check.py --check` works from anywhere in the SKU.
        root = a.check or (os.getcwd() if os.path.isdir("ProjectSettings")
                           else os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", ".."))
        return check(root)
    try:
        weights = sorted({int(x) for x in (a.weights or "").split(",") if x.strip()})
    except ValueError:
        weights = []
    if not weights:
        print(f"{TAG} ERROR: --instance needs --weights, e.g. --weights 800,900", file=sys.stderr)
        return 2
    ensure_fonttools(argv)
    return instance(a.instance, weights, a.out)


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
